-- rowstile 0.1.0-dev: rs256_sign_in. Generated by rowstile migrate from the policy; don't edit it,
-- change the policy and write the next migration.
-- the same policy; what rowstile makes of it changed

-- a migration is one transaction: outside one, nothing below changes anything
SELECT pg_catalog.set_config('authz_ctx.migration', '9a38b852c08d0e4f', true);
DO $authz_tx$
BEGIN
  IF pg_catalog.current_setting('authz_ctx.migration', true) IS DISTINCT FROM '9a38b852c08d0e4f' THEN
    PERFORM pg_catalog.set_config('authz_migration.read_only', pg_catalog.current_setting('default_transaction_read_only'), false);
    PERFORM pg_catalog.set_config('default_transaction_read_only', 'on', false);
  END IF;
END $authz_tx$;
DO $authz_tx$
BEGIN
  IF pg_catalog.current_setting('authz_ctx.migration', true) IS DISTINCT FROM '9a38b852c08d0e4f' THEN
    RAISE EXCEPTION 'rowstile: this migration must run in one transaction, and its statements are being committed one by one [AZ615]'
      USING HINT = 'nothing was changed, and this session is read-only until the migration''s last statement; run the file with your migration tool, or with psql -1 -f';
  END IF;
END $authz_tx$;

SELECT pg_catalog.set_config('lock_timeout', '10s', true) WHERE pg_catalog.current_setting('lock_timeout') IN ('0', '0ms');
SELECT pg_catalog.set_config('check_function_bodies', 'off', true);

-- this migration starts from the policy the previous one left
DO $authz_guard$
DECLARE v_lock text;
BEGIN
  IF to_regclass('authz.policy_versions') IS NOT NULL THEN
    EXECUTE 'SELECT lock FROM authz.policy_versions ORDER BY id DESC LIMIT 1' INTO v_lock;
  END IF;
  IF v_lock = '9a38b852c08d0e4f' THEN
    RAISE EXCEPTION 'rowstile: this database already holds what this migration brings (it ran here before, or rowstile dev or push took the database there): don''t run it, tell your migration tool it is applied [AZ607]'
      USING HINT = 'Prisma: prisma migrate resolve --applied <the migration''s folder>. Alembic: alembic stamp head. '
                   'Others, and why: rowstile help AZ607';
  ELSIF v_lock IS DISTINCT FROM 'f69705060ddad021' THEN
    RAISE EXCEPTION 'rowstile: this migration changes the policy the migration before it left (%), but the database has % [AZ607]',
      'f69705060ddad021', coalesce(v_lock, 'none')
      USING HINT = 'apply the migrations in order; a database changed with rowstile push or apply since needs the '
                   'migrations from the start (or rowstile apply of the policy the previous migration left) '
                   '(rowstile help AZ607)';
  END IF;
END $authz_guard$;

-- The app role must not be the policy's owner, nor a member of it: the rules would not hold for it
DO $ar$
DECLARE v_app name;
BEGIN
  SELECT a.rolname INTO v_app FROM pg_catalog.pg_roles a
  WHERE a.rolname = 'conf_app' AND NOT a.rolsuper AND pg_catalog.pg_has_role(a.oid, CURRENT_USER, 'MEMBER');
  IF v_app IS NOT NULL THEN
    RAISE EXCEPTION 'the app role % is the role that applies the policy (%), or a member of it: the rules would not hold for it [AZ624]', v_app, CURRENT_USER
      USING HINT = 'the policy''s owner skips row-level security, may turn it off, and is believed without a signature: the app connects as a role of its own, which owns nothing of the database';
  END IF;
END $ar$;

-- Functions below resolve names with the search_path in effect now: the schemas that exist, temporary schema last
DO $sp$
DECLARE v_path text; v_bad text; f record;
BEGIN
  SELECT pg_catalog.string_agg(pg_catalog.format('%I (%s)', pw.schema, pw.who), ', ') INTO v_bad FROM (SELECT n.nspname::text AS schema, w.who
FROM pg_catalog.unnest(pg_catalog.current_schemas(false)) s(name) JOIN pg_catalog.pg_namespace n ON n.nspname = s.name,
LATERAL (SELECT CASE WHEN EXISTS (SELECT 1 FROM pg_catalog.aclexplode(n.nspacl) a
                                  WHERE a.grantee = 0 AND a.privilege_type = 'CREATE') THEN 'PUBLIC'
                ELSE (SELECT pg_catalog.string_agg(ro.rolname::text, ', ' ORDER BY ro.rolname) FROM pg_catalog.pg_roles ro
                      WHERE pg_catalog.has_schema_privilege(ro.oid, n.oid, 'CREATE') AND NOT ro.rolsuper
                        AND ro.rolname <> 'pg_database_owner' AND NOT pg_catalog.pg_has_role(ro.oid, CURRENT_USER, 'MEMBER')
                        AND NOT pg_catalog.pg_has_role(ro.oid, (SELECT d.datdba FROM pg_catalog.pg_database d
                                                               WHERE d.datname = pg_catalog.current_database()), 'MEMBER'))
                END AS who) w
-- a temporary schema is the session's own, and never searched for functions or operators
WHERE w.who IS NOT NULL AND n.nspname !~ '^pg_(toast_)?temp_') pw;
  IF v_bad IS NOT NULL THEN
    RAISE EXCEPTION 'the search path has schemas that roles other than the owner may create objects in: % [AZ612]', v_bad
      USING HINT = 'rowstile''s functions that run as the owner resolve names on this path, so a function made there could run as the owner: revoke CREATE on those schemas, or apply with a search path without them';
  END IF;
  SELECT pg_catalog.string_agg(pg_catalog.quote_ident(s.name), ', ' ORDER BY s.i) INTO v_path
  FROM pg_catalog.unnest(pg_catalog.current_schemas(false)) WITH ORDINALITY s(name, i)
  WHERE s.name::text !~ '^pg_temp_';
  PERFORM pg_catalog.set_config('search_path', pg_catalog.concat_ws(', ', v_path, 'pg_temp'), true);
  -- functions made before (a migration keeps those it doesn't change) take the same path
  FOR f IN SELECT p.oid::regprocedure AS fn FROM pg_catalog.pg_proc p
           WHERE p.pronamespace IN (SELECT n.oid FROM pg_catalog.pg_namespace n WHERE n.nspname IN ('authz', 'authz_gen', 'authz_int'))
             AND EXISTS (SELECT 1 FROM pg_catalog.unnest(p.proconfig) c
                         WHERE c ^@ 'search_path=' AND c <> 'search_path=pg_catalog, pg_temp'
                           AND c <> 'search_path=' || pg_catalog.current_setting('search_path')) LOOP
    EXECUTE pg_catalog.format('ALTER FUNCTION %s SET search_path FROM CURRENT', f.fn);
  END LOOP;
END $sp$;

-- Base objects (kept across re-applies)
CREATE SCHEMA IF NOT EXISTS authz;
REVOKE ALL ON SCHEMA authz FROM PUBLIC;

-- Shares people create in the app, for relations marked 'shared' (and custom role assignments)
CREATE TABLE IF NOT EXISTS authz.shares (
  object_type      text        NOT NULL,
  object_id        text        NOT NULL,
  relation         text        NOT NULL,
  subject_type     text        NOT NULL,
  subject_id       text        NOT NULL,
  subject_relation text        NOT NULL DEFAULT '',
  expires_at       timestamptz,
  created_by       text,
  starts_at        timestamptz,
  caveat           text,
  caveat_args      jsonb,
  created_at       timestamptz DEFAULT now(),
  PRIMARY KEY (object_type, object_id, relation, subject_type, subject_id, subject_relation));
CREATE INDEX IF NOT EXISTS shares_by_subject
  ON authz.shares (subject_type, subject_id, subject_relation, object_type, relation);
REVOKE ALL ON authz.shares FROM PUBLIC;
-- A share with anyone names no one: its id is '*' and its relation '', whatever it was made with (authz_int.canon,
-- authz.share). One stored with others takes them; of two that are then one share, the one stored so stays, else
-- the first made
DELETE FROM authz.shares g USING (
  SELECT s.ctid AS row, row_number() OVER (PARTITION BY s.object_type, s.object_id, s.relation
                                           ORDER BY (s.subject_id, s.subject_relation) <> ('*', ''), s.created_at, s.ctid) AS n
  FROM authz.shares s WHERE s.subject_type = 'anyone') d
WHERE g.ctid = d.row AND d.n > 1;
UPDATE authz.shares SET subject_id = '*', subject_relation = ''
WHERE subject_type = 'anyone' AND (subject_id, subject_relation) <> ('*', '');

-- Custom roles: sets of permissions defined as data, assigned like shares ('role:<id>')
CREATE TABLE IF NOT EXISTS authz.roles (
  id          bigserial PRIMARY KEY,
  owner_type  text NOT NULL,
  owner_id    text NOT NULL,
  object_type text NOT NULL,
  name        text NOT NULL,
  created_by  text,
  created_at  timestamptz DEFAULT now(),
  UNIQUE (owner_type, owner_id, object_type, name));
CREATE TABLE IF NOT EXISTS authz.role_permissions (
  role_id    bigint NOT NULL REFERENCES authz.roles ON DELETE CASCADE,
  permission text   NOT NULL,
  PRIMARY KEY (role_id, permission));
REVOKE ALL ON authz.roles, authz.role_permissions FROM PUBLIC;

-- API keys (only a hash of each is kept)
CREATE TABLE IF NOT EXISTS authz.api_keys (
  id           bigserial PRIMARY KEY,
  user_id      text NOT NULL,
  name         text NOT NULL,
  prefix       text NOT NULL,
  hash         text NOT NULL UNIQUE,
  scopes       text NOT NULL DEFAULT '',
  created_at   timestamptz NOT NULL DEFAULT now(),
  expires_at   timestamptz,
  last_used_at timestamptz,
  revoked_at   timestamptz,
  -- whose key: user_id is the principal's id, of this type
  principal_type text NOT NULL DEFAULT 'user');
-- a principal's keys: listed, and deleted with its row
CREATE INDEX IF NOT EXISTS api_keys_by_principal ON authz.api_keys (principal_type, user_id);
-- Settings for the functions (jwt_secret, jwt_issuer, jwt_audience, jwt_user_claim, jwt_type_claim, ...)
CREATE TABLE IF NOT EXISTS authz.settings (key text PRIMARY KEY, value text NOT NULL);
-- The keys an identity provider signs its tokens with (RS256), as authz.set_jwks stored them: what a check
-- reads and no more, the modulus as a number. A key the set gave no kid is kept under ''
CREATE TABLE IF NOT EXISTS authz.jwt_keys (
  kid      text PRIMARY KEY,
  n        numeric NOT NULL,
  e        integer NOT NULL,
  added_at timestamptz NOT NULL DEFAULT now());
-- The audit trail: every share, role, key, request and impersonation, and relationship changes
CREATE TABLE IF NOT EXISTS authz.audit (
  id               bigserial PRIMARY KEY,
  at               timestamptz NOT NULL DEFAULT clock_timestamp(),
  txid             bigint NOT NULL DEFAULT txid_current(),
  db_role          text,
  user_id          text,
  acting_user      text,
  action           text NOT NULL,
  object_type      text,
  object_id        text,
  relation         text,
  subject_type     text,
  subject_id       text,
  subject_relation text,
  detail           jsonb,
  reason           text);
CREATE INDEX IF NOT EXISTS audit_by_object ON authz.audit (object_type, object_id, at);
REVOKE ALL ON authz.api_keys, authz.settings, authz.jwt_keys, authz.audit FROM PUBLIC;

-- For each object with a share that starts or ends later: the next such time, when authz.announce_timed_shares()
-- announces the object (each share's write puts its times in, a run works out the next). A database made before
-- it: the times its shares have after the last run, as that run (timed_shares_to) left them
-- @object table authz.shares_due
DO $due$ BEGIN
  IF to_regclass('authz.shares_due') IS NULL THEN
    CREATE TABLE authz.shares_due (
      object_type text        NOT NULL,
      object_id   text        NOT NULL,
      at          timestamptz NOT NULL,
      PRIMARY KEY (object_type, object_id));
    INSERT INTO authz.shares_due
    SELECT g.object_type, g.object_id, min(v.at) FROM authz.shares g CROSS JOIN LATERAL (VALUES (g.starts_at), (g.expires_at)) v(at)
    WHERE v.at > coalesce((SELECT s.value::timestamptz FROM authz.settings s WHERE s.key = 'timed_shares_to'), '-infinity')
    GROUP BY g.object_type, g.object_id;
  END IF;
END $due$;
CREATE INDEX IF NOT EXISTS shares_due_by_at ON authz.shares_due (at);
REVOKE ALL ON authz.shares_due FROM PUBLIC;
-- (what an earlier authz.announce_timed_shares() kept, the end of its last run, and the indexes it read: no more)
DELETE FROM authz.settings WHERE key = 'timed_shares_to';
DROP INDEX IF EXISTS authz.shares_by_end, authz.shares_by_start;

-- Change feed: objects whose access may have changed, for caches, search indexes, file stores
CREATE TABLE IF NOT EXISTS authz.changes (
  pos         bigserial PRIMARY KEY,
  at          timestamptz NOT NULL DEFAULT clock_timestamp(),
  txid        bigint NOT NULL DEFAULT txid_current(),
  object_type text NOT NULL,
  object_ids  text[] NOT NULL,
  cause       text NOT NULL);
-- the feed's order: by transaction, then position (authz.changes_since)
CREATE INDEX IF NOT EXISTS changes_in_order ON authz.changes (txid, pos);
-- Access requests, approvals, and emergency access
CREATE TABLE IF NOT EXISTS authz.requests (
  id          bigserial PRIMARY KEY,
  object_type text NOT NULL,
  object_id   text NOT NULL,
  relation    text NOT NULL,
  requester   text NOT NULL,
  reason      text,
  duration    interval,
  status      text NOT NULL DEFAULT 'pending' CHECK (status IN ('pending', 'approved', 'denied', 'cancelled')),
  decided_by  text,
  decided_at  timestamptz,
  note        text,
  created_at  timestamptz NOT NULL DEFAULT now());
-- the pending requests of an object, and a requester's: cancelled when their row goes (decided ones stay, history)
CREATE INDEX IF NOT EXISTS requests_by_object ON authz.requests (object_type, object_id) WHERE status = 'pending';
CREATE INDEX IF NOT EXISTS requests_by_requester ON authz.requests (requester) WHERE status = 'pending';
-- Access reviews: a snapshot of the shares on an object, each kept or revoked by a reviewer
CREATE TABLE IF NOT EXISTS authz.reviews (
  id          bigserial PRIMARY KEY,
  object_type text NOT NULL,
  object_id   text NOT NULL,
  created_by  text,
  created_at  timestamptz NOT NULL DEFAULT now(),
  closes_at   timestamptz,
  closed_at   timestamptz);
CREATE TABLE IF NOT EXISTS authz.review_items (
  review_id        bigint NOT NULL REFERENCES authz.reviews ON DELETE CASCADE,
  item             int    NOT NULL,
  relation         text   NOT NULL,
  subject_type     text   NOT NULL,
  subject_id       text   NOT NULL,
  subject_relation text   NOT NULL,
  expires_at       timestamptz,
  keep             boolean,
  decided_by       text,
  decided_at       timestamptz,
  PRIMARY KEY (review_id, item));
-- The SELECT that masks took away from a role, to give back when they go: the table-wide SELECT, replaced by
-- column privileges (whole), and the SELECT of their own that masked columns had (cols)
CREATE TABLE IF NOT EXISTS authz.masked_tables (
  tbl   text,
  role  text,
  whole boolean NOT NULL,
  cols  text[] NOT NULL,
  PRIMARY KEY (tbl, role));
REVOKE ALL ON authz.changes, authz.requests, authz.reviews, authz.review_items, authz.masked_tables FROM PUBLIC;

-- Every policy the rowstile command applied or removed, with the rowstile version that did it
CREATE TABLE IF NOT EXISTS authz.policy_versions (
  id      bigserial PRIMARY KEY,
  at      timestamptz NOT NULL DEFAULT now(),
  by_role text NOT NULL DEFAULT current_user,
  action  text NOT NULL CHECK (action IN ('apply', 'remove')),
  policy  text,
  files   jsonb NOT NULL DEFAULT '{}',
  version text NOT NULL,
  -- what the migrations' lock file said about this policy (its hash), for the next migration to check
  lock    text);
REVOKE ALL ON authz.policy_versions FROM PUBLIC;

-- Request context for conditions: SET LOCAL authz_ctx.mfa = 'yes', then {authz.ctx('mfa') = 'yes'}. A key
-- not set is NULL. Once a connection has set a key, Postgres reads it as '' in a later transaction that didn't, so
-- '' is NULL too: what an earlier request on a pooled connection set must not show
CREATE OR REPLACE FUNCTION authz.ctx(key text) RETURNS text LANGUAGE sql STABLE AS
  $$ SELECT nullif(current_setting('authz_ctx.' || key, true), '') $$;

-- Link tokens the request presents: SET LOCAL authz_ctx.links = '<token>,<token>'
CREATE OR REPLACE FUNCTION authz.link_hashes() RETURNS text[] LANGUAGE sql STABLE AS $$
  SELECT coalesce(array_agg(encode(sha256(convert_to(btrim(x), 'UTF8')), 'hex')), '{}')
  FROM unnest(string_to_array(nullif(current_setting('authz_ctx.links', true), ''), ',')) x
  WHERE btrim(x) <> '' $$;

-- Inheritance tables kept whose tables have other tables under them since they were computed (a partition
-- attached or detached: no trigger saw those rows) are computed again
DO $stale$
DECLARE r record;
BEGIN
  IF to_regclass('authz_int.trees') IS NULL THEN RETURN; END IF;
  FOR r IN SELECT n.name, n.oids, n.fn FROM (VALUES ('folder__parent__tree', ARRAY[to_regclass('"app"."folders"')::oid]::oid[] || ARRAY(WITH RECURSIVE below(oid) AS (
    SELECT i.inhrelid FROM pg_catalog.pg_inherits i WHERE i.inhparent = ANY (ARRAY[to_regclass('"app"."folders"')::oid]::oid[])
    UNION SELECT i.inhrelid FROM pg_catalog.pg_inherits i JOIN below b ON i.inhparent = b.oid)
  SELECT b.oid FROM below b ORDER BY b.oid), 'authz_int."folder__parent__tree_rebuild"()')) n(name, oids, fn)
           JOIN authz_int.trees t ON t.name = n.name
           WHERE t.oids IS DISTINCT FROM n.oids AND to_regprocedure(n.fn) IS NOT NULL LOOP
    EXECUTE format('SELECT %s', r.fn);
    UPDATE authz_int.trees SET oids = r.oids WHERE name = r.name;
  END LOOP;
END $stale$;

-- What the app role evaluates itself (its rules, the views they read, the rules' own functions, the masked views)
-- calls nothing of the app's that may read data: a call the condition's text doesn't show isn't run as the owner
DO $ac$
DECLARE r record;
BEGIN
  FOR r IN
    WITH RECURSIVE read(classid, objid, what) AS (
      SELECT x.classid, x.objid, x.what FROM (
        SELECT 'pg_policy'::regclass::oid AS classid, p.oid AS objid,
               format('the %s rule of %s', substr(p.polname::text, 7), p.polrelid::regclass) AS what
        FROM pg_policy p JOIN pg_description d ON d.objoid = p.oid AND d.classoid = 'pg_policy'::regclass
         AND d.description IN ('rowstile')
        UNION ALL
        SELECT 'pg_proc'::regclass::oid, f.oid, 'the rules of ' || split_part(f.proname::text, ':', 1)
        FROM pg_proc f WHERE f.pronamespace = 'authz_gen'::regnamespace
        UNION ALL
        SELECT 'pg_rewrite'::regclass::oid, w.oid, 'the masked view ' || c.oid::regclass
        FROM pg_class c JOIN pg_description d ON d.objoid = c.oid AND d.classoid = 'pg_class'::regclass
         AND d.description IN ('rowstile masked view')
        JOIN pg_rewrite w ON w.ev_class = c.oid) x
      UNION
      -- (the views they read, and those these read: a view runs what it calls as whoever reads it)
      SELECT 'pg_rewrite'::regclass::oid, w.oid, rd.what
      FROM read rd JOIN pg_depend dep ON dep.classid = rd.classid AND dep.objid = rd.objid
       AND dep.refclassid = 'pg_class'::regclass
      JOIN pg_class v ON v.oid = dep.refobjid AND v.relkind = 'v' AND v.relnamespace = 'authz_int'::regnamespace
      JOIN pg_rewrite w ON w.ev_class = v.oid)
    SELECT rd.what, fn.oid::regprocedure::text AS fn
    FROM read rd JOIN pg_depend dep ON dep.classid = rd.classid AND dep.objid = rd.objid
    JOIN pg_proc fn ON fn.oid = CASE dep.refclassid
        WHEN 'pg_proc'::regclass THEN dep.refobjid
        WHEN 'pg_operator'::regclass THEN (SELECT o.oprcode FROM pg_operator o WHERE o.oid = dep.refobjid) END
    WHERE fn.pronamespace NOT IN (SELECT n.oid FROM pg_namespace n
                                  WHERE n.nspname IN ('pg_catalog', 'authz', 'authz_gen', 'authz_int'))
      AND fn.provolatile <> 'i'
      AND fn.prolang NOT IN (SELECT l.oid FROM pg_language l WHERE l.lanname IN ('internal', 'c'))
    ORDER BY 1, 2 LIMIT 1
  LOOP
    RAISE EXCEPTION '%: a condition calls %, and nothing in its text shows the call (a function of the row read as a column, a cast, an operator written OPERATOR(...)), so the app role would run it with its own rights, not the policy''s [AZ628]', r.what, r.fn
      USING HINT = 'call it by its name, with parentheses, on the row''s columns, as {app.blocked_doc(this.id)}: rowstile then runs it with the policy''s rights. A function that reads nothing may be marked IMMUTABLE instead';
  END LOOP;
END $ac$;

-- Bytes read as a number, the first byte the highest (a key's modulus, a signature): seven bytes at a time
CREATE FUNCTION authz_int.b2n(p bytea) RETURNS numeric
LANGUAGE plpgsql IMMUTABLE STRICT AS $f$
DECLARE h text := encode(p, 'hex'); r numeric := 0;
BEGIN
  h := repeat('0', (14 - length(h) % 14) % 14) || h;
  FOR i IN 0..length(h) / 14 - 1 LOOP
    r := r * 72057594037927936 + ('x00' || substr(h, i * 14 + 1, 14))::bit(64)::bigint;
  END LOOP;
  RETURN r;
END $f$;

-- An RSA signature checked in SQL (RSASSA-PKCS1-v1_5 with SHA-256, RFC 8017 section 8.2.2), for JWT signatures
-- (RS256): the signature raised to the key's exponent under its modulus, compared with the encoding of the
-- message's hash built whole, so nothing is parsed out of the signature. Refused before anything is computed: an
-- exponent other than 65537 (with 1, a signature would be its own encoding), a modulus under 2048 bits or over
-- 4096, a signature that isn't as long as the modulus, and one that isn't below it (s + n says what s says)
CREATE FUNCTION authz_int.rsa_ok(p_sig bytea, p_n numeric, p_e int, p_msg bytea) RETURNS boolean
LANGUAGE plpgsql IMMUTABLE STRICT AS $f$
DECLARE k int := length(p_sig); s numeric; r numeric := 1; e int := p_e;
BEGIN
  IF p_e <> 65537 OR k NOT BETWEEN 256 AND 512
     OR p_n < authz_int.b2n(decode('01' || repeat('00', k - 1), 'hex'))
     OR p_n > authz_int.b2n(decode(repeat('ff', k), 'hex')) THEN
    RETURN false;
  END IF;
  s := authz_int.b2n(p_sig);
  IF s >= p_n THEN
    RETURN false;
  END IF;
  WHILE e > 0 LOOP
    IF e & 1 = 1 THEN r := (r * s) % p_n; END IF;
    s := (s * s) % p_n;
    e := e >> 1;
  END LOOP;
  RETURN r = authz_int.b2n(decode('0001' || repeat('ff', k - 54) || '003031300d060960864801650304020105000420', 'hex')
                           || sha256(p_msg));
END $f$;

-- The note that a token's signature was checked against a key, on this connection: an HMAC, with the key that
-- signs sessions (which the app role can't read), of the token, this backend and the key's modulus. authz.login_jwt
-- keeps the notes of the tokens it checked in a setting of the connection, and doesn't check again a token whose
-- note is there: an RSA check costs more than the read it guards. A note says no more than the check did (that
-- this token is signed by this key), so the token's time, issuer, audience and user are read at every sign-in. It
-- can't be made up without the key, is no note on another connection, and is none once the kid has another key.
CREATE FUNCTION authz_int.token_note(p_token text, p_n numeric) RETURNS text
LANGUAGE plpgsql STABLE STRICT SECURITY DEFINER SET search_path = pg_catalog, pg_temp AS $f$
DECLARE k authz_int.session_key;
BEGIN
  SELECT * INTO k FROM authz_int.session_key;
  RETURN left(encode(sha256(k.opad || sha256(k.ipad || convert_to(to_jsonb(ARRAY[
    'a checked token', encode(sha256(convert_to(p_token, 'UTF8')), 'hex'), pg_backend_pid()::text, p_n::text
  ])::text, 'UTF8'))), 'hex'), 32);
END $f$;

-- Store the keys your identity provider signs its tokens with (RS256): its key set as it serves it (a JWKS, RFC
-- 7517), which replaces the stored one. For the tables' owner (an administrator, a job that runs when the keys
-- rotate): whoever writes a key signs in as anyone.
--   SELECT * FROM authz.set_jwks('{"keys": [...]}')
-- Kept: RSA keys for signatures (use absent or sig, key_ops absent or with verify, alg absent or RS256) of 2048
-- to 4096 bits with the exponent 65537. A row for each key says what became of it: added, replaced (its kid has
-- another key now), kept, removed (it left the set), or skipped, and why. A set that leaves no key is refused,
-- saying why each key was skipped, and the stored keys stay: a fetch that failed must not sign everyone out.
CREATE FUNCTION authz.set_jwks(p_jwks jsonb) RETURNS TABLE (kid text, change text, why text)
LANGUAGE plpgsql SECURITY DEFINER SET search_path = pg_catalog, pg_temp AS $f$
DECLARE k jsonb; v_n numeric; v_e numeric; v_kids text[] := '{}'; v_ns numeric[] := '{}'; r record;
        v_skipped text[] := '{}';
BEGIN
  FOR k IN SELECT x FROM jsonb_array_elements(CASE WHEN jsonb_typeof(p_jwks->'keys') = 'array' THEN p_jwks->'keys'
                                                   ELSE '[]' END) x LOOP
    kid := coalesce(k->>'kid', ''); change := 'skipped'; why := NULL; v_n := NULL; v_e := NULL;
    IF k->>'kty' IS DISTINCT FROM 'RSA' THEN
      why := 'not an RSA key';
    ELSIF (k ? 'use' AND k->>'use' IS DISTINCT FROM 'sig')
          OR (k ? 'key_ops' AND NOT coalesce(k->'key_ops' ? 'verify', false)) THEN
      why := 'not a key for signatures';
    ELSIF k ? 'alg' AND k->>'alg' IS DISTINCT FROM 'RS256' THEN
      why := 'for another algorithm than RS256';
    ELSIF kid = ANY (v_kids) THEN
      why := 'the same kid as a key before it';
    ELSE
      BEGIN
        v_n := authz_int.b2n(authz_int.b64url(k->>'n'));
        v_e := authz_int.b2n(authz_int.b64url(k->>'e'));
      EXCEPTION WHEN OTHERS THEN
        v_n := NULL;
      END;
      IF v_n IS NULL OR v_e IS NULL THEN
        why := 'no modulus and exponent in base64url';
      ELSIF v_e <> 65537 THEN
        why := 'an exponent other than 65537';
      ELSIF v_n < authz_int.b2n(decode('80' || repeat('00', 255), 'hex'))
            OR v_n >= authz_int.b2n(decode('01' || repeat('00', 512), 'hex')) THEN
        why := 'a modulus under 2048 bits or over 4096';
      END IF;
    END IF;
    IF why IS NULL THEN
      v_kids := v_kids || kid; v_ns := v_ns || v_n;
    ELSE
      v_skipped := v_skipped || (CASE WHEN kid = '' THEN 'a key with no kid' ELSE 'key ' || kid END || ': ' || why);
      RETURN NEXT;
    END IF;
  END LOOP;
  IF cardinality(v_kids) = 0 THEN
    RAISE EXCEPTION 'the key set holds no key to check tokens with (an RSA key for signatures, 2048 to 4096 bits, exponent 65537)'
      USING ERRCODE = 'invalid_parameter_value',
            DETAIL = CASE WHEN cardinality(v_skipped) = 0 THEN 'it holds no keys at all'
                          ELSE array_to_string(v_skipped[1:10], '; ') END,
            HINT = 'the stored keys stay as they were (rowstile help AZ719)';
  END IF;
  why := NULL;
  FOR r IN DELETE FROM authz.jwt_keys j WHERE j.kid <> ALL (v_kids) RETURNING j.kid AS gone LOOP
    kid := r.gone; change := 'removed';
    RETURN NEXT;
  END LOOP;
  FOR i IN 1..cardinality(v_kids) LOOP
    kid := v_kids[i];
    IF EXISTS (SELECT 1 FROM authz.jwt_keys j WHERE j.kid = v_kids[i] AND j.n = v_ns[i] AND j.e = 65537) THEN
      change := 'kept';
    ELSIF EXISTS (SELECT 1 FROM authz.jwt_keys j WHERE j.kid = v_kids[i]) THEN
      UPDATE authz.jwt_keys j SET n = v_ns[i], e = 65537, added_at = now() WHERE j.kid = v_kids[i];
      change := 'replaced';
    ELSE
      INSERT INTO authz.jwt_keys AS j (kid, n, e) VALUES (v_kids[i], v_ns[i], 65537);
      change := 'added';
    END IF;
    RETURN NEXT;
  END LOOP;
  PERFORM authz_int.audit('set_jwks', NULL, NULL, NULL, NULL, NULL, NULL, jsonb_build_object('kids', to_jsonb(v_kids)));
END $f$;

-- Sign in with a JWT for this transaction: SELECT authz.login_jwt('eyJ...'). The token's alg says how it is
-- checked and nothing else does: HS256 against the secret alone (authz.settings jwt_secret), RS256 against the
-- keys authz.set_jwks stored alone, the one the token's kid names (a token that names none: the stored key, when
-- there is one only). So a public key never reaches the HMAC, and a check that isn't set up is never chosen.
-- Other settings (authz.settings): jwt_issuer, jwt_audience, jwt_user_claim (default sub),
-- jwt_type_claim (a claim naming the principal's type, for services; absent or 'user': a user).
-- Tokens must carry exp.
-- A 'scope' claim (space separated) limits the transaction to those policy scopes.
CREATE OR REPLACE FUNCTION authz.login_jwt(p_token text) RETURNS text
LANGUAGE plpgsql SECURITY DEFINER SET search_path = pg_catalog, pg_temp AS $f$
DECLARE parts text[] := string_to_array(coalesce(p_token, ''), '.'); v_head jsonb; v_claims jsonb; v_secret text;
        v_user text; v_type text; v_scopes text[]; v_now numeric := extract(epoch FROM now()); v_want text;
        v_key authz.jwt_keys; v_note text; v_notes text[];
BEGIN
  SELECT value INTO v_secret FROM authz.settings WHERE key = 'jwt_secret';
  IF v_secret IS NULL AND NOT EXISTS (SELECT 1 FROM authz.jwt_keys) THEN RAISE EXCEPTION 'JWT login is not configured (authz.settings jwt_secret, or keys stored with authz.set_jwks)' USING ERRCODE = 'invalid_authorization_specification', HINT = 'rowstile help AZ703'; END IF;
  BEGIN
    IF cardinality(parts) <> 3 THEN RAISE EXCEPTION 'bad'; END IF;
    v_head := convert_from(authz_int.b64url(parts[1]), 'UTF8')::jsonb;
    v_claims := convert_from(authz_int.b64url(parts[2]), 'UTF8')::jsonb;
    IF v_head->>'alg' = 'HS256' AND v_secret IS NOT NULL THEN
      -- the signatures compared through their hashes: the time it takes says nothing of how much of the token's is right
      IF sha256(authz_int.b64url(parts[3]))
         IS DISTINCT FROM sha256(authz_int.hmac_sha256(convert_to(v_secret, 'UTF8'),
                                                       convert_to(parts[1] || '.' || parts[2], 'UTF8'))) THEN
        RAISE EXCEPTION 'bad';
      END IF;
    ELSIF v_head->>'alg' = 'RS256' THEN
      IF v_head ? 'kid' THEN
        SELECT j.* INTO v_key FROM authz.jwt_keys j WHERE j.kid = v_head->>'kid';
      ELSIF (SELECT count(*) FROM authz.jwt_keys) = 1 THEN
        SELECT j.* INTO v_key FROM authz.jwt_keys j;
      END IF;
      -- a token this connection checked against this key already has its note among the connection's
      -- (authz_int.token_note), and its signature is not checked again; the notes compared through their hashes
      v_note := authz_int.token_note(p_token, v_key.n);
      IF v_note IS NULL OR NOT EXISTS (
           SELECT 1 FROM unnest(string_to_array(current_setting('authz.checked_tokens', true), ' ')) x
           WHERE sha256(convert_to(x, 'UTF8')) = sha256(convert_to(v_note, 'UTF8'))) THEN
        IF v_key.kid IS NULL OR authz_int.rsa_ok(authz_int.b64url(parts[3]), v_key.n, v_key.e,
                                                 convert_to(parts[1] || '.' || parts[2], 'UTF8')) IS NOT TRUE THEN
          RAISE EXCEPTION 'bad';
        END IF;
        -- the newest 64 are kept, for as long as the connection lasts (once this transaction commits: a setting)
        v_notes := coalesce(string_to_array(current_setting('authz.checked_tokens', true), ' '), '{}') || v_note;
        PERFORM set_config('authz.checked_tokens',
                           array_to_string(v_notes[greatest(1, cardinality(v_notes) - 63):], ' '), false);
      END IF;
    ELSE
      RAISE EXCEPTION 'bad';
    END IF;
  EXCEPTION WHEN OTHERS THEN
    RAISE EXCEPTION 'invalid token' USING ERRCODE = 'invalid_authorization_specification', HINT = 'rowstile help AZ703';
  END;
  -- an expiry is required; both are numbers of seconds
  IF jsonb_typeof(v_claims->'exp') IS DISTINCT FROM 'number' OR (v_claims->>'exp')::numeric <= v_now
     OR (v_claims ? 'nbf' AND (jsonb_typeof(v_claims->'nbf') <> 'number' OR (v_claims->>'nbf')::numeric > v_now)) THEN
    RAISE EXCEPTION 'token expired or not yet valid' USING ERRCODE = 'invalid_authorization_specification', HINT = 'rowstile help AZ703';
  END IF;
  SELECT value INTO v_want FROM authz.settings WHERE key = 'jwt_issuer';
  IF v_want IS NOT NULL AND v_claims->>'iss' IS DISTINCT FROM v_want THEN
    RAISE EXCEPTION 'token from another issuer' USING ERRCODE = 'invalid_authorization_specification', HINT = 'rowstile help AZ703';
  END IF;
  SELECT value INTO v_want FROM authz.settings WHERE key = 'jwt_audience';
  -- (coalesce: without the claim both sides are NULL, and a token that names no audience is not for this one)
  IF v_want IS NOT NULL AND NOT coalesce(v_claims->>'aud' = v_want
       OR (jsonb_typeof(v_claims->'aud') = 'array' AND v_claims->'aud' ? v_want), false) THEN
    RAISE EXCEPTION 'token for another audience' USING ERRCODE = 'invalid_authorization_specification', HINT = 'rowstile help AZ703';
  END IF;
  v_user := v_claims->>coalesce((SELECT value FROM authz.settings WHERE key = 'jwt_user_claim'), 'sub');
  v_type := v_claims->>(SELECT value FROM authz.settings WHERE key = 'jwt_type_claim');
  IF coalesce(v_type, 'user') <> 'user' AND NOT EXISTS (SELECT 1 FROM authz_int.types WHERE name = v_type AND principal) THEN
    RAISE EXCEPTION 'the token names a type that does not sign in' USING ERRCODE = 'invalid_authorization_specification', HINT = 'rowstile help AZ703';
  END IF;
  v_user := coalesce(authz_int.canon(coalesce(v_type, 'user'), v_user), '');
  v_type := CASE WHEN coalesce(v_type, 'user') = 'user' THEN '' ELSE v_type END;
  PERFORM authz_int.one_principal(v_type, v_user);
  PERFORM set_config('authz.user_id', v_user, true);
  PERFORM set_config('authz.principal_type', v_type, true);
  PERFORM set_config('authz.acting_user', '', true);
  IF v_claims ? 'scope' THEN
    v_scopes := ARRAY(SELECT x FROM unnest(string_to_array(v_claims->>'scope', ' ')) x
                      WHERE EXISTS (SELECT 1 FROM authz_int.scope_items WHERE scope = x));
    PERFORM set_config('authz.scopes', CASE WHEN cardinality(v_scopes) = 0 THEN '(none)'
                                            ELSE array_to_string(v_scopes, ',') END, true);
  ELSE
    PERFORM set_config('authz.scopes', '', true);
  END IF;
  PERFORM authz_int.sign();
  IF NOT EXISTS (SELECT 1 FROM authz.principal()) THEN
    RAISE EXCEPTION 'the token names no active user' USING ERRCODE = 'invalid_authorization_specification', HINT = 'rowstile help AZ703';
  END IF;
  PERFORM authz_int.jit_off();
  RETURN authz_int.actor();
END $f$;

-- The partitions of each table with rules and the tables that inherit from one: row-level security on, with
-- no policies of their own, so they are read and written through it only (read directly, they would skip its rules
-- and triggers). Every apply and every migration: one made or attached since is closed too (it alone is locked,
-- as CHILD_TRIGGERS locks only one that lacks the triggers)
DO $rls$
DECLARE c regclass;
BEGIN
  FOR c IN WITH RECURSIVE d(oid) AS (
             SELECT i.inhrelid FROM pg_catalog.pg_inherits i
             WHERE i.inhparent = ANY (SELECT to_regclass(x)::oid FROM unnest(ARRAY['"app"."folders"', '"app"."inbox"', '"app"."notes"', '"app"."projects"']::text[]) x)
             UNION SELECT i.inhrelid FROM pg_catalog.pg_inherits i JOIN d ON i.inhparent = d.oid)
           SELECT d.oid::regclass FROM d JOIN pg_catalog.pg_class k ON k.oid = d.oid WHERE NOT k.relrowsecurity LOOP
    EXECUTE format('ALTER TABLE %s ENABLE ROW LEVEL SECURITY', c);
  END LOOP;
END $rls$;

-- The partitions of a table rowstile watches and the tables that inherit from it: the triggers made above, on
-- each, for the rows stored there and the statements on it
DO $ch$
DECLARE r record;
BEGIN
  FOR r IN SELECT * FROM authz_int.child_triggers() LOOP
    EXECUTE r.stmt;
    EXECUTE pg_catalog.format('COMMENT ON TRIGGER %I ON %s IS %L', r.name, r.child, 'rowstile: the trigger of the table above, for the rows stored here');
  END LOOP;
END $ch$;

REVOKE SELECT ON ALL TABLES IN SCHEMA authz_gen, authz_int FROM "conf_app";
GRANT SELECT ON authz_gen.policy_lines, authz_int."folder__edit", authz_int."folder__edit__direct", authz_int."project__edit", authz_int."project__member", authz_int."project__owner", authz_int."project__service", authz_int."project__view" TO "conf_app";

-- Privileges the policy doesn't give on rowstile's schemas and what is in them are taken back
DO $r$
DECLARE g record; v_taken int := 0;
BEGIN
  FOR g IN SELECT n.nspname::text AS object, gw.who, a.privilege_type AS privilege,
       format('REVOKE %s ON SCHEMA %I FROM %s CASCADE', a.privilege_type, n.nspname, gw.who) AS stmt
  FROM pg_namespace n, aclexplode(n.nspacl) a, LATERAL (SELECT CASE a.grantee WHEN 0 THEN 'PUBLIC' ELSE a.grantee::regrole::text END AS who) gw
  WHERE n.nspname IN ('authz', 'authz_gen', 'authz_int') AND a.grantee <> n.nspowner
    AND NOT (a.grantee = '"conf_app"'::regrole AND n.nspname <> 'authz_int' AND a.privilege_type = 'USAGE')
UNION ALL
SELECT c.oid::regclass::text, gw.who, a.privilege_type,
       format('REVOKE %s ON %s %s FROM %s CASCADE', a.privilege_type, CASE c.relkind WHEN 'S' THEN 'SEQUENCE' ELSE 'TABLE' END,
              c.oid::regclass, gw.who)
  FROM pg_class c, aclexplode(c.relacl) a, LATERAL (SELECT CASE a.grantee WHEN 0 THEN 'PUBLIC' ELSE a.grantee::regrole::text END AS who) gw
  WHERE c.relnamespace IN (SELECT oid FROM pg_namespace WHERE nspname IN ('authz', 'authz_gen', 'authz_int')) AND a.grantee <> c.relowner
    AND NOT (a.grantee = '"conf_app"'::regrole AND a.privilege_type = 'SELECT'
             AND c.relnamespace::regnamespace::text || '."' || replace(c.relname, '"', '""') || '"' = ANY (ARRAY['authz_gen."policy_lines"', 'authz_int."folder__edit"', 'authz_int."folder__edit__direct"', 'authz_int."project__edit"', 'authz_int."project__member"', 'authz_int."project__owner"', 'authz_int."project__service"', 'authz_int."project__view"']::text[]))
UNION ALL
SELECT format('%s (%I)', c.oid::regclass, att.attname), gw.who, a.privilege_type,
       format('REVOKE %s (%I) ON %s FROM %s CASCADE', a.privilege_type, att.attname, c.oid::regclass, gw.who)
  FROM pg_class c JOIN pg_attribute att ON att.attrelid = c.oid, aclexplode(att.attacl) a, LATERAL (SELECT CASE a.grantee WHEN 0 THEN 'PUBLIC' ELSE a.grantee::regrole::text END AS who) gw
  WHERE c.relnamespace IN (SELECT oid FROM pg_namespace WHERE nspname IN ('authz', 'authz_gen', 'authz_int')) AND att.attacl IS NOT NULL
UNION ALL
SELECT p.oid::regprocedure::text, gw.who, a.privilege_type,
       format('REVOKE %s ON ROUTINE %s FROM %s CASCADE', a.privilege_type, p.oid::regprocedure, gw.who)
  FROM pg_proc p, aclexplode(p.proacl) a, LATERAL (SELECT CASE a.grantee WHEN 0 THEN 'PUBLIC' ELSE a.grantee::regrole::text END AS who) gw
  WHERE p.pronamespace IN (SELECT oid FROM pg_namespace WHERE nspname IN ('authz', 'authz_gen', 'authz_int')) AND a.grantee <> p.proowner
    AND NOT (p.pronamespace = 'authz_int'::regnamespace AND a.grantee IN (0, '"conf_app"'::regrole))
    AND NOT (p.pronamespace = 'authz_gen'::regnamespace AND a.grantee = '"conf_app"'::regrole
             AND '"' || replace(p.proname, '"', '""') || '"' = ANY (ARRAY['"app.folders:rules:explain"', '"app.folders:update:items"', '"app.folders:update:refuse"', '"app.folders:update:why"', '"app.inbox:insert:items"', '"app.inbox:insert:refuse"', '"app.inbox:insert:why"', '"app.inbox:rules:explain"', '"app.notes:delete:items"', '"app.notes:delete:why"', '"app.notes:insert:items"', '"app.notes:insert:refuse"', '"app.notes:insert:why"', '"app.notes:rules:explain"', '"app.notes:update:items"', '"app.notes:update:refuse"', '"app.notes:update:why"', '"app.projects:rules:explain"']::text[]))
    AND NOT (p.pronamespace = 'authz'::regnamespace AND a.grantee = '"conf_app"'::regrole AND p.oid = ANY (ARRAY['authz.uid()', 'authz.principal()', 'authz.ctx(text)', 'authz.link_hashes()', 'authz.act_as(text, text)', 'authz.sign_out()', 'authz.connection_check()', 'authz.session_limited()', 'authz.can(text, text, text)', 'authz.list(text, text, text, integer)', 'authz.perms(text, text)', 'authz.perms_of(text, text[])', 'authz.share(text, text, text, text, text, text, timestamptz, timestamptz, text, jsonb)', 'authz.unshare(text, text, text, text, text, text)', 'authz.create_link(text, text, text, timestamptz)', 'authz.list_links(text, text)', 'authz.revoke_link(text, text, text)', 'authz.create_role(text, text, text, text, text[])', 'authz.set_role_permissions(bigint, text[])', 'authz.delete_role(bigint)', 'authz.roles_of(text, text)', 'authz.who(text, text, text)', 'authz.explain(text, text, text, text)', 'authz.list_shares(text, text)', 'authz.explain_rule(text, text, text, jsonb)', 'authz.who_among(text, text, text, text[], text)', 'authz.create_api_key(text, text, timestamptz, text, text)', 'authz.list_api_keys(text, text)', 'authz.revoke_api_key(bigint)', 'authz.login_key(text)', 'authz.login_jwt(text)', 'authz.view_as(text, text)', 'authz.request_access(text, text, text, text, interval)', 'authz.pending_requests()', 'authz.decide_request(bigint, boolean, text)', 'authz.cancel_request(bigint)', 'authz.break_glass(text, text, text, text, interval)', 'authz.start_review(text, text, timestamptz)', 'authz.review_items(bigint)', 'authz.review_decide(bigint, integer, boolean)', 'authz.close_review(bigint, boolean)', 'authz.who(text, bigint, text)', 'authz.explain(text, bigint, text, text)', 'authz.list_shares(text, bigint)', 'authz.list_links(text, bigint)', 'authz.revoke_link(text, bigint, text)', 'authz.create_link(text, bigint, text, timestamptz)', 'authz.create_role(text, bigint, text, text, text[])', 'authz.roles_of(text, bigint)', 'authz.request_access(text, bigint, text, text, interval)', 'authz.break_glass(text, bigint, text, text, interval)', 'authz.start_review(text, bigint, timestamptz)', 'authz.can(text, bigint, text)', 'authz.who_among(text, bigint, text, text[], text)', 'authz.perms(text, bigint)', 'authz.share(text, text, text, text, bigint, text, timestamptz, timestamptz, text, jsonb)', 'authz.unshare(text, text, text, text, bigint, text)', 'authz.share(text, bigint, text, text, text, text, timestamptz, timestamptz, text, jsonb)', 'authz.unshare(text, bigint, text, text, text, text)', 'authz.share(text, bigint, text, text, bigint, text, timestamptz, timestamptz, text, jsonb)', 'authz.unshare(text, bigint, text, text, bigint, text)']::regprocedure[])) LOOP
    EXECUTE g.stmt;
    v_taken := v_taken + 1;
  END LOOP;
  IF v_taken > 0 THEN
    RAISE WARNING 'took back % privileges on rowstile''s schemas that the policy doesn''t give (default privileges of the owner, or grants made since the last apply)', v_taken;
  END IF;
END $r$;

